      --prestige-border: rgba(192, 158, 109, 0.25);
      --prestige-glow: rgba(255, 71, 87, 0.6);
      /* [核心字体] - 保持不变 */
      --title-font: 'Anton', 'Noto Serif SC', sans-serif;
      --body-font: 'Inter', 'Noto Serif SC', sans-serif;

      /* [布局变量] */
      --container-padding-desktop: 25px;
      --container-padding-mobile: 20px;
      --block-padding: 18px;
      --block-gap: 20px;
    }

    /* --- 主题配色定义 --- */
    .theme-celestial {
      --prestige-bg-start: #3e000c; --prestige-bg-end: #000000;
      --prestige-text: #f5ede0; --prestige-accent: #ff4757;
      --prestige-gold: #c09e6d; --prestige-secondary-text: #b8a994;
      --prestige-border: rgba(192, 158, 109, 0.25); --prestige-glow: rgba(255, 71, 87, 0.6);
    }
    .theme-dark {
      --prestige-bg-start: #16161a; --prestige-bg-end: #121214;
      --prestige-text: #fffffe; --prestige-accent: #7f5af0;
      --prestige-gold: #2cb67d; --prestige-secondary-text: #94a1b2;
      --prestige-border: rgba(148, 161, 178, 0.2); --prestige-glow: rgba(127, 90, 240, 0.6);
    }
    .theme-light {
      --prestige-bg-start: #f8f9fa; --prestige-bg-end: #eff1f3;
      --prestige-text: #212529; --prestige-accent: #6c757d;
      --prestige-gold: #adb5bd; --prestige-secondary-text: #495057;
      --prestige-border: rgba(108, 117, 125, 0.15); --prestige-glow: rgba(108, 117, 125, 0.5);
    }
    .theme-gray {
      --prestige-bg-start: #dee2e6; --prestige-bg-end: #d1d5d9;
      --prestige-text: #212529; --prestige-accent: #495057;
      --prestige-gold: #adb5bd; --prestige-secondary-text: #6c757d;
      --prestige-border: rgba(73, 80, 87, 0.15); --prestige-glow: rgba(73, 80, 87, 0.5);
    }
    .theme-summer-green {
      --prestige-bg-start: #b7e4c7; --prestige-bg-end: #a8dcc0;
      --prestige-text: #1b4332; --prestige-accent: #40916c;
      --prestige-gold: #d8f3dc; --prestige-secondary-text: #2d6a4f;
      --prestige-border: rgba(45, 106, 79, 0.2); --prestige-glow: rgba(64, 145, 108, 0.6);
    }
    .theme-pink-blue {
      --prestige-bg-start: #f8f9fa; --prestige-bg-end: #eef2f3;
      --prestige-text: #3a5a40; --prestige-accent: #90e0ef;
      --prestige-gold: #ffc6ff; --prestige-secondary-text: #588157;
      --prestige-border: rgba(144, 224, 239, 0.25); --prestige-glow: rgba(144, 224, 239, 0.6);
    }
    .theme-classic-green {
      --prestige-bg-start: #3a5a40; --prestige-bg-end: #314d36;
      --prestige-text: #dad7cd; --prestige-accent: #588157;
      --prestige-gold: #dad7cd; --prestige-secondary-text: #a3b18a;
      --prestige-border: rgba(218, 215, 205, 0.2); --prestige-glow: rgba(88, 129, 87, 0.6);
    }
    .theme-ancient {
      --prestige-bg-start: #f5e7de; --prestige-bg-end: #f1e2d6;
      --prestige-text: #4a3f35; --prestige-accent: #8a5a44;
      --prestige-gold: #d4a59a; --prestige-secondary-text: #8b5a2b;
      --prestige-border: rgba(139, 90, 43, 0.15); --prestige-glow: rgba(138, 90, 68, 0.6);
    }
    .theme-summer-blue {
      --prestige-bg-start: #ade8f4; --prestige-bg-end: #a0e2f2;
      --prestige-text: #03045e; --prestige-accent: #48cae4;
      --prestige-gold: #caf0f8; --prestige-secondary-text: #0077b6;
      --prestige-border: rgba(0, 119, 182, 0.2); --prestige-glow: rgba(72, 202, 228, 0.6);
    }
    .theme-lavender {
      --prestige-bg-start: #f8f9fa; --prestige-bg-end: #f1f3f8;
      --prestige-text: #3a0ca3; --prestige-accent: #cdb4db;
      --prestige-gold: #ffc8dd; --prestige-secondary-text: #7209b7;
      --prestige-border: rgba(205, 180, 219, 0.25); --prestige-glow: rgba(205, 180, 219, 0.6);
    }
    .theme-cream {
      --prestige-bg-start: #faedcd; --prestige-bg-end: #f8e9c5;
      --prestige-text: #6b3e26; --prestige-accent: #ffd166;
      --prestige-gold: #fefae0; --prestige-secondary-text: #d4a373;
      --prestige-border: rgba(214, 162, 112, 0.2); --prestige-glow: rgba(255, 209, 102, 0.6);
    }
    .theme-ink {
      --prestige-bg-start: #dad7cd; --prestige-bg-end: #d2cfc5;
      --prestige-text: #344e41; --prestige-accent: #3a5a40;
      --prestige-gold: #588157; --prestige-secondary-text: #3a5a40;
      --prestige-border: rgba(58, 90, 64, 0.2); --prestige-glow: rgba(58, 90, 64, 0.6);
    }

    /* --- [核心优化]: 背景融合与滚动条美化 --- */
    body {
      margin: 0;
      padding: 0; /* 移除body的内边距，让容器完全贴合 */
      background: transparent; /* 背景设为透明 */
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    ::-webkit-scrollbar { width: 8px; }
    ::-webkit-scrollbar-track { background: rgba(0,0,0,0.3); }
    ::-webkit-scrollbar-thumb { background: var(--prestige-gold); border-radius: 4px; }
    ::-webkit-scrollbar-thumb:hover { background: var(--prestige-accent); }

    /* --- 核心容器 --- */
    .status-bar-data-container { display: none; }
    .status-bar-container {
      width: 100%;
      background: radial-gradient(ellipse at top, var(--prestige-bg-start), var(--prestige-bg-end) 70%);
      color: var(--prestige-text);
      font-family: var(--body-font);
      border-top: 1px solid var(--prestige-gold);
      border-bottom: 1px solid var(--prestige-gold);
      box-shadow: 0 0 35px rgba(176, 141, 87, 0.25), inset 0 0 20px rgba(62, 0, 12, 0.6);
      overflow: hidden;
      display: flex;
      flex-direction: column;
      min-height: 100px; /* 最小高度，避免折叠时内容消失 */
      transition: all 0.4s ease-in-out;
    }

    /* --- 头部区域 --- */
    .status-bar-header {
      padding: var(--container-padding-mobile);
      border-bottom: 1px solid var(--prestige-border);
      text-align: left;
      position: relative;
      cursor: pointer;
      -webkit-tap-highlight-color: transparent;
    }
    .main-title {
      font-family: var(--title-font);
      font-size: 2.5rem;
      font-weight: 400;
      line-height: 1.1;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      color: var(--prestige-text);
      text-shadow: 0 0 8px var(--prestige-glow), 1px 1px 3px rgba(0,0,0,0.7);
      padding-right: 60px; /* 为切换器留出空间 */
    }
    .quote {
      font-family: 'Noto Serif SC', serif;
      font-weight: 400; font-style: normal;
      font-size: 0.95rem;
      color: var(--prestige-secondary-text); margin-top: 15px;
      padding-left: 15px; border-left: 3px solid var(--prestige-accent);
      transition: all 0.3s ease;
    }

    /* --- 配色切换器样式 --- */
    .theme-switcher {
      position: absolute;
      top: 15px;
      right: 15px;
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
      justify-content: flex-end;
      max-width: 100px;
    }
    .theme-button {
      width: 18px; height: 18px;
      border-radius: 50%;
      cursor: pointer;
      border: 3px solid var(--button-outer-color, black);
      background-color: var(--button-inner-color, grey);
      box-sizing: border-box;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
      flex-shrink: 0;
    }
    .theme-button:hover {
      transform: scale(1.15);
      box-shadow: 0 0 8px rgba(255, 255, 255, 0.5);
    }
    .theme-button.active {
      border-width: 4px;
      box-shadow: 0 0 10px var(--prestige-glow);
    }

    /* --- 响应式内容区 --- */
    .content-area {
      flex-grow: 1;
      display: grid; grid-template-columns: 1fr; /* 移动端默认为单列 */
      transition: opacity 0.4s ease-in-out, transform 0.4s ease-in-out;
      will-change: opacity, transform;
    }
    .left-column, .right-column {
      display: flex; flex-direction: column;
      gap: var(--block-gap); padding: var(--container-padding-mobile);
    }
    .left-column { border-bottom: 1px solid var(--prestige-border); /* 移动端列之间用下边框分隔 */ }

    /* --- 折叠状态样式 --- */
    .status-bar-container.collapsed .content-area {
      opacity: 0;
      transform: translateY(-20px);
      max-height: 0;
      overflow: hidden;
      padding: 0 !important; /* 强制移除padding */
      pointer-events: none;
    }
    .status-bar-container.collapsed .status-bar-header {
      border-bottom-color: transparent;
    }
    .status-bar-container.collapsed .quote {
        max-height: 0;
        opacity: 0;
        margin-top: 0;
        padding-left: 0;
        overflow: hidden;
    }


    /* --- [新增功能]: 底部折叠区域样式 --- */
    .status-bar-footer {
        height: 15px;
        cursor: pointer;
        width: 100%;
        flex-shrink: 0;
        transition: height 0.4s ease-in-out;
        -webkit-tap-highlight-color: transparent;
    }
    .status-bar-container.collapsed .status-bar-footer {
        height: 0;
    }

    /* --- 数据块样式 --- */
    .data-block {
      background: rgba(255, 255, 255, 0.025);
      padding: var(--block-padding); border-radius: 8px;
      border: 1px solid transparent; transition: all 0.3s ease;
      opacity: 0; animation: fadeIn 0.6s ease-out forwards;
    }
    .data-block:hover {
      border-color: var(--prestige-border); transform: translateY(-3px);
      box-shadow: 0 5px 15px rgba(0,0,0,0.4);
    }

    /* 动画延迟 */
    .left-column .data-block:nth-child(1) { animation-delay: 0.1s; }
    .left-column .data-block:nth-child(2) { animation-delay: 0.2s; }
    .left-column .data-block:nth-child(3) { animation-delay: 0.3s; }
    .right-column .data-block:nth-child(1) { animation-delay: 0.4s; }
    .right-column .data-block:nth-child(2) { animation-delay: 0.5s; }
    .right-column .data-block:nth-child(3) { animation-delay: 0.6s; }
    .right-column .data-block:nth-child(4) { animation-delay: 0.7s; }

    .data-block-title {
      font-family: var(--title-font); font-size: 1.2rem;
      text-transform: uppercase; letter-spacing: 1px;
      color: var(--prestige-text);
      border-bottom: 1px solid var(--prestige-border); padding-bottom: 10px;
      margin-bottom: 12px; display: flex; align-items: center;
    }
    .data-block-title::before {
      content: ''; display: inline-block;
      width: 10px; height: 10px;
      background-color: var(--prestige-accent); margin-right: 12px;
      border-radius: 3px; box-shadow: 0 0 6px var(--prestige-glow);
    }

    .data-item {
      display: flex; justify-content: space-between; align-items: center;
      padding: 8px 0; font-size: 0.9rem;
    }
    .data-key {
      font-weight: 500; color: var(--prestige-secondary-text);
      flex-shrink: 0; margin-right: 15px;
    }
    .data-value {
      font-weight: 400; text-align: right;
      word-break: break-word; color: var(--prestige-text);
    }
    .data-item.long-text-item {
      flex-direction: column; align-items: flex-start;
    }
    .data-item.long-text-item .data-value {
      text-align: left; margin-top: 6px; width: 100%; line-height: 1.6;
    }

    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(20px); }
      to { opacity: 1; transform: translateY(0); }
    }

    /* --- 桌面端布局 (@media query) --- */
    @media (min-width: 800px) {
      .status-bar-header { padding: var(--container-padding-desktop); }
      .theme-switcher {
          top: 25px; right: 25px; max-width: none;
      }
      .content-area {
        grid-template-columns: 2fr 3fr; /* 桌面端恢复双列 */
      }
      .left-column, .right-column { padding: var(--container-padding-desktop); }
      .left-column {
        border-right: 1px solid var(--prestige-border);
        border-bottom: none; /* 移除移动端的下边框 */
      }
      .main-title { font-size: 3.5rem; }
      .quote { font-size: 1.05rem; }
      .data-block-title { font-size: 1.3rem; }
      .data-item { font-size: 0.95rem; }
    }
  </style>
</head>
<body>

  <div class="status-bar-data-container">$1</div>

  <div class="status-bar-container">
    <header class="status-bar-header"></header>
    <main class="content-area">
      <div class="left-column"></div>
      <div class="right-column"></div>
    </main>
    <footer class="status-bar-footer"></footer>
  </div>

<script>
    (function() {
      document.addEventListener('DOMContentLoaded', () => {
        const dataContainer = document.querySelector('.status-bar-data-container');
        const container = document.querySelector('.status-bar-container');
        const headerArea = document.querySelector('.status-bar-header');
        const leftColumn = document.querySelector('.left-column');
        const rightColumn = document.querySelector('.right-column');
        const footerArea = document.querySelector('.status-bar-footer');

        if (!container || !dataContainer || !headerArea || !leftColumn || !rightColumn || !footerArea) {
          console.error('Luminaris Status Bar: Critical elements missing.');
          return;
        }

        const themes = {
          'celestial': { main: '#ff4757', accent: '#c09e6d' },
          'dark': { main: '#7f5af0', accent: '#2cb67d' },
          'light': { main: '#6c757d', accent: '#adb5bd' },
          'gray': { main: '#495057', accent: '#adb5bd' },
          'summer-green': { main: '#40916c', accent: '#d8f3dc' },
          'pink-blue': { main: '#90e0ef', accent: '#ffc6ff' },
          'classic-green': { main: '#588157', accent: '#dad7cd' },
          'ancient': { main: '#8a5a44', accent: '#d4a59a' },
          'summer-blue': { main: '#48cae4', accent: '#caf0f8' },
          'lavender': { main: '#cdb4db', accent: '#ffc8dd' },
          'cream': { main: '#ffd166', accent: '#fefae0' },
          'ink': { main: '#3a5a40', accent: '#588157' }
        };

        function initializeControls() {
            const switcher = document.createElement('div');
            switcher.className = 'theme-switcher';
            Object.keys(themes).forEach(themeName => {
                const button = document.createElement('button');
                button.className = 'theme-button';
                button.dataset.theme = themeName;
                button.title = themeName;
                button.style.setProperty('--button-inner-color', themes[themeName].main);
                button.style.setProperty('--button-outer-color', themes[themeName].accent);

                button.addEventListener('click', (e) => {
                    e.stopPropagation(); // 阻止事件冒泡到header
                    applyTheme(themeName, true);
                });
                switcher.appendChild(button);
            });
            // 将切换器添加到header的子元素中
            const headerContent = headerArea.querySelector('.main-title, .quote')?.parentElement || headerArea;
            headerContent.appendChild(switcher);

            const savedTheme = localStorage.getItem('luminaris-theme') || 'celestial';
            applyTheme(savedTheme, false);

            container.classList.add('collapsed');

            // 折叠/展开事件监听
            headerArea.addEventListener('click', (e) => {
                if (e.target.closest('.theme-switcher')) return; // 如果点击的是切换器，则不折叠
                container.classList.toggle('collapsed');
            });
            footerArea.addEventListener('click', () => {
                container.classList.toggle('collapsed');
            });
        }

        function applyTheme(themeName, save = true) {
            Object.keys(themes).forEach(t => container.classList.remove(`theme-${t}`));
            container.classList.add(`theme-${themeName}`);

            document.querySelectorAll('.theme-button').forEach(btn => {
                btn.classList.toggle('active', btn.dataset.theme === themeName);
            });
            if (save) {
                localStorage.setItem('luminaris-theme', themeName);
            }
        }

        // **核心整合点**: 使用旧版的数据解析逻辑
        function parseData(text) {
            const data = { blocks: [] };
            const blockRegex = /\[([^\]]+)\]([\s\S]*?)\[\/\1\]/g;
            let match;

            while ((match = blockRegex.exec(text)) !== null) {
                const blockName = match[1].trim();
                // 忽略 config 和 本期焦点 块
                if (blockName.toLowerCase() === 'config' || blockName.toLowerCase() === '本期焦点') continue;

                const blockContent = match[2].trim();
                const items = {};
                const lines = blockContent.split('\n').filter(line => line.trim() !== '');

                lines.forEach(line => {
                    const parts = line.match(/^([^:]+):\s*(.*)/);
                    if (parts && parts.length === 3) {
                        items[parts[1].trim()] = parts[2].trim();
                    }
                });
                data.blocks.push({ name: blockName, items: items });
            }
            return data;
        }

        // **核心整合点**: 使用旧版的数据渲染逻辑
        function renderData(data) {
          leftColumn.innerHTML = '';
          rightColumn.innerHTML = '';
          headerArea.innerHTML = ''; // 先清空header

          // 渲染封面故事
          const coverStory = data.blocks.find(b => b.name === '封面故事');
          if (coverStory && coverStory.items) {
            const title = coverStory.items['主打标题'] || '本期焦点';
            const quote = coverStory.items['引言'] || '';
            headerArea.innerHTML = `
              <div class="main-title">${title}</div>
              <p class="quote">${quote}</p>
            `;
          } else {
            // 如果没有封面故事，提供一个默认标题
            headerArea.innerHTML = `<div class="main-title">Awaiting Signal...</div><p class="quote">Your story is about to unfold.</p>`;
          }

          // 渲染数据块
          const blockDistribution = {
              left: ['生命体征', '核心档案', '专业评估'],
              right: ['价值分析', '圈内观察', '媒体信息', '时局变数']
          };
          const blocksMap = new Map(data.blocks.map(b => [b.name, b]));

          blockDistribution.left.forEach(name => {
              if (blocksMap.has(name)) {
                leftColumn.appendChild(createBlockElement(blocksMap.get(name)));
              }
          });
          blockDistribution.right.forEach(name => {
              if (blocksMap.has(name)) {
                rightColumn.appendChild(createBlockElement(blocksMap.get(name)));
              }
          });
        }

        // **核心整合点**: 使用旧版的数据块创建逻辑
        function createBlockElement(blockData) {
            const blockDiv = document.createElement('div');
            blockDiv.className = 'data-block';

            const itemsHTML = Object.entries(blockData.items).map(([key, value]) => {
                const isLongText = value.length > 25 || ['时代风向', '履历亮点', '业界评价', '当前机遇', '潜在风险'].includes(key);
                const itemClass = isLongText ? 'data-item long-text-item' : 'data-item';

                return `
                  <div class="${itemClass}">
                    <span class="data-key">${key}</span>
                    <span class="data-value">${value}</span>
                  </div>`;
            }).join('');

            blockDiv.innerHTML = `<div class="data-block-title">${blockData.name}</div>${itemsHTML}`;
            return blockDiv;
        }

        // 主执行流程
        const rawData = dataContainer.textContent.trim();
        if (rawData) {
          try {
            const parsedData = parseData(rawData);
            renderData(parsedData);
          } catch (error) {
            console.error('Luminaris Status Bar: Failed to parse or render data.', error);
            headerArea.innerHTML = `<div class="main-title">Data Error</div><p class="quote">Failed to process incoming signal.</p>`;
          }
        } else {
            headerArea.innerHTML = `<div class="main-title">Awaiting Signal...</div><p class="quote">Your story is about to unfold.</p>`;
        }

        // 最后初始化所有控件（如配色切换器、折叠事件）
        initializeControls();
      });
    })();
  </script>

</body>
</html>
